#include <bits/stdc++.h>
using namespace std;
using Key=pair<vector<int>,vector<array<int,3>>>;
struct F{uint64_t mask; int sign;};
int modpow(int a,int e,int p){int v=1;while(e){if(e&1)v=v*a%p;a=a*a%p;e>>=1;}return v;}
void need(bool b,const string&s){if(!b)throw runtime_error(s);}
vector<pair<int,int>> edgelist(int n){vector<pair<int,int>> e;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)e.push_back({a,b});return e;}
// Completely different census: split every permutation into unordered path blocks.
vector<F> census(int n){auto es=edgelist(n);int ix[8][8]={};for(int i=0;i<(int)es.size();i++)ix[es[i].first][es[i].second]=i;vector<int>w(n);iota(w.begin(),w.end(),0);map<Key,F> m;
 do{for(int cut=0;cut<(1<<(n-1));cut++){vector<int> iso;vector<array<int,3>> paths;uint64_t mask=0;int sign=1;
 for(int a=0;a<n;){int b=a;while(b<n-1&&!(cut>>b&1))b++;if(a==b)iso.push_back(w[a]);else{int l=w[a],r=w[b];paths.push_back({min(l,r),max(l,r),(b-a-1)%2});int s=1;for(int j=a;j<b;j++){int x=w[j],y=w[j+1];mask|=1ull<<ix[min(x,y)][max(x,y)];s*=x<y?1:-1;}if(l>r&&(b-a)%2)s=-s;sign*=s;}a=b+1;}
 sort(iso.begin(),iso.end());sort(paths.begin(),paths.end());Key k{iso,paths};auto it=m.find(k);if(it==m.end()||mask<it->second.mask)m[k]={mask,sign};else if(mask==it->second.mask)need(sign==it->second.sign,"duplicate sign disagreement");
 }}while(next_permutation(w.begin(),w.end()));vector<F>v;for(auto &x:m)v.push_back(x.second);return v;}
// Independent path-component census: enumerate canonical paths, then use an exact-cover recursion anchored at the smallest unused vertex.
vector<F> census8(){
 const int n=8; auto es=edgelist(n); int ix[8][8]={};for(int i=0;i<(int)es.size();i++)ix[es[i].first][es[i].second]=i;
 struct Path{int vertices;uint64_t edges;int sign;array<int,3> label;};vector<Path> paths[8];vector<int>w;
 function<void(int)> build=[&](int used){if(w.size()>=2&&w.front()<w.back()){int sg=1;uint64_t mask=0;for(int j=1;j<(int)w.size();j++){int a=w[j-1],b=w[j];sg*=a<b?1:-1;mask|=1ull<<ix[min(a,b)][max(a,b)];}paths[__builtin_ctz((unsigned)used)].push_back({used,mask,sg,{w.front(),w.back(),int(w.size()-2)%2}});}for(int i=0;i<n;i++)if(!(used>>i&1)){w.push_back(i);build(used|1<<i);w.pop_back();}};build(0);
 map<Key,F> found;vector<array<int,3>> labels;function<void(int,uint64_t,int)> cover=[&](int used,uint64_t edges,int sign){if(used==255){auto v=labels;sort(v.begin(),v.end());Key k{{},v};auto it=found.find(k);if(it==found.end()||edges<it->second.mask)found[k]={edges,sign};else if(edges==it->second.mask)need(sign==it->second.sign,"component sign disagreement");return;}int first=__builtin_ctz((unsigned)(255^used));for(auto &q:paths[first])if(!(q.vertices&used)){labels.push_back(q.label);cover(used|q.vertices,edges|q.edges,sign*q.sign);labels.pop_back();}};cover(0,0,1);vector<F>v;for(auto &x:found)v.push_back(x.second);return v;
}
// Endpoints are prescribed; enumerate endpoint-pair paths over ordered interior subsets, then exact-cover all vertices.
vector<F> census10(int r){
 const int n=10, E=(1<<(2*r))-1;auto es=edgelist(n);int ix[10][10]={};for(int i=0;i<(int)es.size();i++)ix[es[i].first][es[i].second]=i;
 struct Path{int vertices;uint64_t edges;int sign;array<int,3> label;};vector<Path>paths[10];vector<int>w;
 function<void(int)> extend=[&](int used){for(int end=w.front()+1;end<2*r;end++)if(!(used>>end&1)){int v=used|1<<end,sg=1;uint64_t bits=0;for(int j=1;j<(int)w.size();j++){int a=w[j-1],b=w[j];sg*=a<b?1:-1;bits|=1ull<<ix[min(a,b)][max(a,b)];}int a=w.back();sg*=a<end?1:-1;bits|=1ull<<ix[min(a,end)][max(a,end)];paths[__builtin_ctz((unsigned)v)].push_back({v,bits,sg,{w.front(),end,int(w.size()-1)%2}});}for(int i=2*r;i<n;i++)if(!(used>>i&1)){w.push_back(i);extend(used|1<<i);w.pop_back();}};for(int a=0;a<2*r;a++){w={a};extend(1<<a);}
 map<Key,F>found;vector<array<int,3>> labels;function<void(int,uint64_t,int)>cover=[&](int used,uint64_t mask,int sign){if(used==1023){auto v=labels;sort(v.begin(),v.end());Key k{{},v};auto it=found.find(k);if(it==found.end()||mask<it->second.mask)found[k]={mask,sign};else if(mask==it->second.mask)need(sign==it->second.sign,"same forest sign mismatch");return;}int first=__builtin_ctz((unsigned)(1023^used));for(auto &q:paths[first])if(!(q.vertices&used)){labels.push_back(q.label);cover(used|q.vertices,mask|q.edges,sign*q.sign);labels.pop_back();}};cover(0,0,1);vector<F>v;for(auto &x:found)v.push_back(x.second);return v;
}
struct C{int N;vector<pair<int,int>> g;};
vector<C> load(const string &path,int n){ifstream f(path);need((bool)f,"can't open contexts");vector<C>v;string line;while(getline(f,line)){istringstream in(line);int N,k;need(bool(in>>N>>k),"header");need(N>=n&&N<101&&k>=0,"bad size");set<pair<int,int>>seen;C c{N,{}};for(int j=0;j<k;j++){int x,y;need(bool(in>>x>>y),"truncated edge");need(x>=0&&y>=0&&x<N&&y<N&&x!=y,"edge bounds or loop");if(x>y)swap(x,y);need(y>=n,"old-old edge");need(seen.insert({x,y}).second,"duplicate edge");c.g.push_back({x,y});}string extra;need(!(in>>extra),"trailing input");v.push_back(c);}return v;}
// DSU recognizes cycles; then walk each component to orient it and evaluate sign.
int value(int n,const F&f,const C&c,int p){auto es=edgelist(n);vector<pair<int,int>>edges=c.g;for(int i=0;i<(int)es.size();i++)if(f.mask>>i&1)edges.push_back(es[i]);vector<vector<int>>ad(c.N);vector<int>pa(c.N);iota(pa.begin(),pa.end(),0);function<int(int)> root=[&](int x){return pa[x]==x?x:pa[x]=root(pa[x]);};for(auto [a,b]:edges){if(ad[a].size()==2||ad[b].size()==2)return 0;int x=root(a),y=root(b);if(x==y)return 0;pa[x]=y;ad[a].push_back(b);ad[b].push_back(a);}int components=c.N-(int)edges.size(),r=0,sg=f.sign;vector<bool>vis(c.N);for(int i=0;i<c.N;i++)if(ad[i].size()==1&&!vis[i]){r++;int prev=-1,cur=i,len=0;vis[cur]=true;while(true){int next=-1;for(int q:ad[cur])if(q!=prev)next=q;if(next<0)break;if(cur>next)sg=-sg;prev=cur;cur=next;vis[cur]=true;len++;}if(len%2)return 0;}
 int z=modpow(2,r,p);for(int j=2;j<=components;j++)z=z*j%p;z=z*modpow(modpow(2,components-1,p),p-2,p)%p;return sg<0?(p-z)%p:z;}
struct R{int rank,det;};
R rankmat(vector<vector<uint8_t>> a,int p){int h=a.size(),w=a[0].size(),r=0,det=1;uint8_t tab[103][103];for(int i=0;i<p;i++)for(int j=0;j<p;j++)tab[i][j]=i*j%p;for(int c=0;c<w&&r<h;c++){int piv=r;while(piv<h&&!a[piv][c])piv++;if(piv==h)continue;if(piv!=r){swap(a[piv],a[r]);det=(p-det)%p;}int x=a[r][c];det=det*x%p;int inv=modpow(x,p-2,p);for(int j=c;j<w;j++)a[r][j]=tab[inv][a[r][j]];for(int i=r+1;i<h;i++)if(a[i][c]){auto t=tab[a[i][c]];for(int j=c+1;j<w;j++){int q=a[i][j]-t[a[r][j]];a[i][j]=q+(q<0?p:0);}a[i][c]=0;}r++;}return {r,h==w&&r==h?det:-1};}

// Return zero for invalid support, or canonical sign and exact combinatorial magnitude parameters.
struct Info{int sign,c,r;};
Info info(const F&f,const vector<pair<int,int>>&g,int N){auto es=edgelist(10);int deg[100]={},a[100][2],parent[100];iota(parent,parent+N,0);function<int(int)>root=[&](int x){return parent[x]==x?x:parent[x]=root(parent[x]);};int edges=0;auto add=[&](int x,int y){if(deg[x]>=2||deg[y]>=2)return false;int p=root(x),q=root(y);if(p==q)return false;parent[p]=q;a[x][deg[x]++]=y;a[y][deg[y]++]=x;edges++;return true;};for(int i=0;i<(int)es.size();i++)if(f.mask>>i&1){auto [x,y]=es[i];if(!add(x,y))return {0,0,0};}for(auto [x,y]:g)if(!add(x,y))return {0,0,0};int sg=f.sign,r=0;bool seen[100]={};for(int i=0;i<N;i++)if(deg[i]==1&&!seen[i]){int at=i,prev=-1,len=0;r++;seen[at]=1;while(true){int v=-1;for(int j=0;j<deg[at];j++)if(a[at][j]!=prev)v=a[at][j];if(v<0)break;sg*=at<v?1:-1;prev=at;at=v;seen[at]=1;len++;}if(len%2)return {0,0,0};}return {sg,N-edges,r};}
int main(int argc,char**argv){try{need(argc==3,"usage: verify_kernel reps vectors");auto fs=census10(4);need(fs.size()==735,"wrong dimension");ifstream rep(argv[1]);for(auto f:fs){uint64_t m;int sign;need(bool(rep>>m>>sign)&&m==f.mask&&sign==f.sign,"rep mismatch");}int extra;need(!(rep>>extra),"extra reps");ifstream in(argv[2]);int K[735][56];for(auto &row:K)for(auto &x:row)need(bool(in>>x),"short kernel");need(!(in>>extra),"extra kernel");for(int p:{101,103}){vector<vector<uint8_t>> a(735,vector<uint8_t>(56));for(int i=0;i<735;i++)for(int j=0;j<56;j++)a[i][j]=(K[i][j]%p+p)%p;auto q=rankmat(a,p);need(q.rank==56,"kernel vectors dependent");cout<<"kernel column rank mod "<<p<<" = "<<q.rank<<"\n";}
 // Construct one definitely nonzero diagram around representative zero.
 auto es=edgelist(10);vector<vector<int>> adj(10);for(int i=0;i<(int)es.size();i++)if(fs[0].mask>>i&1){auto [a,b]=es[i];adj[a].push_back(b);adj[b].push_back(a);}vector<pair<int,int>> sample;int M=10;bool vis[10]={};for(int i=0;i<10;i++)if(adj[i].size()==1&&!vis[i]){int at=i,prev=-1,len=0;vis[at]=true;while(true){int next=-1;for(int z:adj[at])if(z!=prev)next=z;if(next<0)break;prev=at;at=next;vis[at]=true;len++;}int end=at;sample.emplace_back(i,M++);sample.emplace_back(end,M++);if(len%2){int last=M-1;sample.emplace_back(last,M);M++;}}
 need(info(fs[0],sample,M).sign!=0,"positive control vanished");
 // Extra disconnected components: an even path has a common scalar; odd paths and cycles kill every column.
 auto even=sample;even.emplace_back(M,M+1);even.emplace_back(M+1,M+2);auto odd=sample;odd.emplace_back(M,M+1);auto cycle=even;cycle.emplace_back(M+2,M);
 auto rel=sample;auto perm=[&](int x){return x<10?x:10+(M-1-x);};int gauge=1;for(auto &e:rel){int x=perm(e.first),y=perm(e.second);if((e.first<e.second)!=(x<y))gauge=-gauge;e={x,y};}
 auto un=sample;auto it=find_if(un.begin(),un.end(),[](auto e){return e.first==0||e.second==0;});need(it!=un.end(),"missing test endpoint");un.erase(it);auto sat=un;sat.emplace_back(0,M);sat.emplace_back(M,M+1);
 bool sawzero=false,sawnonzero=false;for(auto f:fs){auto q=info(f,sample,M),z=info(f,even,M+3),o=info(f,odd,M+2),cy=info(f,cycle,M+3),per=info(f,rel,M),u=info(f,un,M),v=info(f,sat,M+2);if(!q.sign)sawzero=true;else sawnonzero=true;need(!o.sign&&!cy.sign,"odd/cycle hostile");need(q.sign==z.sign&&(!q.sign||(z.c==q.c+1&&z.r==q.r+1)),"even-disconnected control");need(per.sign==gauge*q.sign&&(!q.sign||(per.c==q.c&&per.r==q.r)),"relabel gauge control");need(u.sign==v.sign&&(!u.sign||(u.c==v.c&&u.r==v.r)),"two-edge-tail saturation");}need(sawzero&&sawnonzero,"zero/nonzero columns control");long long baseline=0;for(int j=0;j<735;j++)baseline+=(long long)info(fs[j],sample,M).sign*K[j][0];need(baseline==0&&baseline+info(fs[0],sample,M).sign!=0,"kernel corruption hostile");cout<<"cycle, disconnected even/odd paths, relabel gauge, tail saturation, zero columns, kernel corruption: PASS\n";
 long checked=0,zero=0;vector<pair<int,int>> bridges;vector<int>stubs;function<void(unsigned)> classify=[&](unsigned rem){if(!rem){int groups=bridges.size()+stubs.size();for(int par=0;par<(1<<groups);par++){vector<pair<int,int>> g;int N=10,ix=0;for(auto [x,y]:bridges){int len=2+((par>>ix++)&1),at=x;for(int z=1;z<len;z++){g.emplace_back(at,N);at=N++;}g.emplace_back(at,y);}for(int x:stubs){int len=1+((par>>ix++)&1),at=x;while(len--){g.emplace_back(at,N);at=N++;}}checked++;long long sums[56]={};int nz=0,C=-1,R=-1;for(int j=0;j<735;j++){auto q=info(fs[j],g,N);if(!q.sign)continue;nz++;if(C<0){C=q.c;R=q.r;}else need(q.c==C&&q.r==R,"nonconstant exact magnitude");for(int k=0;k<56;k++)sums[k]+=(long long)q.sign*K[j][k];}if(!nz)zero++;for(int k=0;k<56;k++)need(sums[k]==0,"integer kernel violation");}return;}int x=__builtin_ctz(rem);rem^=1u<<x;stubs.push_back(x);classify(rem);stubs.pop_back();for(int y=x+1;y<8;y++)if(rem>>y&1){bridges.emplace_back(x,y);classify(rem^(1u<<y));bridges.pop_back();}};classify(255);need(checked==32400&&zero==17042,"unexpected diagram totals");cout<<"canonical diagrams="<<checked<<", zero="<<zero<<", exact integer annihilation PASS\n";
 }catch(exception &e){cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
